Real-World Practical Example: Fetching Weather Data with Loading Spinner and Error Handling

Imagine a weather app on your mobile screen:
1. When user clicks 'Search', turn on loading spinner.
2. Call weather API using a Promise.
3. If success (.then): Show temperature and city name.
4. If failed (.catch): Show 'City not found or Network Error' message.
5. In all cases (.finally): Turn off loading spinner.

function fetchCityWeather(cityName) {
  // Show spinner
  showLoadingSpinner(true);

  fetch(`https://api.weather.com/v1/${cityName}`)
    .then(response => {
      if (!response.ok) {
        throw new Error("City not found or server error");
      }
      return response.json(); // Parses JSON and returns a new promise
    })
    .then(weatherData => {
      displayWeather(weatherData);
    })
    .catch(error => {
      showErrorMessage(error.message);
    })
    .finally(() => {
      // Always hide spinner, whether success or error!
      showLoadingSpinner(false);
    });
}

