// Student-Friendly Practical Example: Understanding Promise States & Microtasks
function checkTicketBooking(availableSeats) {
  console.log("Step 1: Booking request initiated...");

  return new Promise((resolve, reject) => {
    console.log("Step 2: Checking seat availability in database...");

    setTimeout(() => {
      if (availableSeats > 0) {
        // Fulfilled state: We have seats!
        resolve({ status: "CONFIRMED", seatNumber: "B-14" });
      } else {
        // Rejected state: No seats left!
        reject(new Error("Sorry, all seats are already booked!"));
      }
    }, 1000);
  });
}

console.log("Start of Program");

// Calling the Promise function
checkTicketBooking(2)
  .then((ticket) => {
    console.log("Step 4 (Success): Ticket Confirmed! Seat:", ticket.seatNumber);
    return "SMS Notification Sent to User";
  })
  .then((notificationStatus) => {
    console.log("Step 5 (Chained):", notificationStatus);
  })
  .catch((err) => {
    console.error("Step 4 (Failure): Booking Failed! Reason:", err.message);
  })
  .finally(() => {
    console.log("Step 6 (Cleanup): Booking session closed. Thank you!");
  });

console.log("End of Program (Notice this logs BEFORE the Promise finishes!)");

